input.sparql:
SELECT ?point ?class ?ts WHERE {
  ?point a brick:ElectricPower ;
        ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
  OPTIONAL { ?point rdfs:label ?lbl }
}

SELECT ?p (str(?c) AS ?class) WHERE {
  ?p a ?c .
  FILTER (strcontains(str(?c), "Power") || strcontains(str(?c), "Energy") || strcontains(str(?c), "Electric"))
}

SELECT ?sensor ?ref ?ts WHERE {
  ?sensor a brick:Electric_Power_Sensor .
  ?sensor ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
}
